CREATE TABLE IF NOT EXISTS import_batch_rows (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, batch_id BIGINT UNSIGNED NOT NULL, excel_row INT NOT NULL, supplier_code VARCHAR(60) NOT NULL, supplier_name VARCHAR(160) NOT NULL, supplier_phone VARCHAR(30), supplier_invoice VARCHAR(100) NOT NULL, purchase_date DATE NOT NULL, item_code VARCHAR(80) NOT NULL, product_name VARCHAR(190) NOT NULL, barcode VARCHAR(100), serial_number VARCHAR(190), brand VARCHAR(100), unit VARCHAR(30), category VARCHAR(100), cost_price DECIMAL(18,4) NOT NULL, retail_price DECIMAL(18,2) NOT NULL, wholesale_price DECIMAL(18,2) NOT NULL, purchase_quantity DECIMAL(14,3) NOT NULL, validation_status ENUM('valid','warning','error') NOT NULL, messages TEXT, raw_data JSON NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(batch_id), INDEX(item_code), INDEX(supplier_code,supplier_invoice), FOREIGN KEY(batch_id) REFERENCES import_batches(id)) ENGINE=InnoDB;
